contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address caller, address[] memory tos, uint[] memory vs) public payable {
        require(tos.length == vs.length);
        require(tos.length > 0);

        address beforeFrom = c.from();
        address beforeCaddress = c.caddress();
        uint beforeContractBalance = address(c).balance;

        bool reverted;
        bool ok;
        try c.transfer(tos, vs) returns (bool r) {
            ok = r;
            reverted = false;
        } catch {
            ok = false;
            reverted = true;
        }

        address afterFrom = c.from();
        address afterCaddress = c.caddress();
        uint afterContractBalance = address(c).balance;

        assert(reverted || (ok == true && afterFrom == beforeFrom && afterCaddress == beforeCaddress && afterContractBalance >= beforeContractBalance));
    }

    receive() external payable {}
}

